(function(){
'use strict';
function ar(){return document.documentElement.lang!=='en';}
function t(a,b){return ar()?a:b;}
function phaseCard(number,title,desc,href,cta,extra){return '<article class="release-phase-card"><div class="release-phase-top"><span class="release-phase-number">'+number+'</span><span class="release-phase-status">'+t('متاح الآن','AVAILABLE NOW')+'</span></div><h3>'+title+'</h3><p>'+desc+'</p><div class="release-phase-tags">'+extra.map(x=>'<span>'+x+'</span>').join('')+'</div><a href="'+href+'">'+cta+' <span aria-hidden="true">'+t('←','→')+'</span></a></article>';}
function suite(){return '<section id="miyar-release-home" class="release-suite" aria-labelledby="release-suite-title"><div class="lp-wrap"><div class="release-suite-head"><div><span class="lp-eyebrow">'+t('منصة واحدة · ثلاث مراحل مترابطة','ONE PLATFORM · THREE CONNECTED PHASES')+'</span><h2 id="release-suite-title">'+t('من الاستراتيجية إلى تصميم الوظائف،<br><em>تخطيط القوى العاملة والتعويضات.</em>','From strategy to job architecture,<br><em>workforce planning and compensation.</em>')+'</h2></div><p>'+t('معيار يربط قرار العمل من بدايته إلى تنفيذه: يولّد حزمة OD قابلة للمراجعة، يحسب فجوة القوى العاملة بالسيناريوهات، ثم يربط الدرجة بنطاق التعويض المعتمد لدى الجهة.','Miyar carries the workforce decision end to end: generate a reviewable OD package, quantify the workforce gap with scenarios, then connect the evaluated grade to the organization-approved compensation band.')+'</p></div><div class="release-phase-grid">'+
phaseCard('01',t('التطوير التنظيمي وتصميم الوظيفة','OD & Job Architecture'),t('حوّل الهدف والمسؤوليات إلى مسمى وغرض ووصف وظيفي وجدارات ومؤشرات أداء وعائلة ومسار مهني، ثم اربطها بـSSCO والتعليم والتقييم والاعتماد.','Turn strategy and responsibilities into title, purpose, JD, competencies, KPIs, job family and career path, then connect them to SSCO, education, evaluation and approval.'),'#enterprise/create',t('افتح محرك OD','Open OD Engine'),[t('وصف وظيفي كامل','Full JD'),t('SSCO + التعليم','SSCO + Education'),t('الدرجة والمسار','Grade + Career Path')])+
phaseCard('02',t('تخطيط القوى العاملة','Manpower Planning'),t('حوّل الطلب المتوقع والطاقة الإنتاجية والعرض الحالي إلى Required FTE وForecast Supply وفجوة واضحة عبر سيناريوهات محافظة وأساسية وعالية.','Convert demand, productivity and current supply into Required FTE, Forecast Supply and a transparent gap across lower, base and higher-demand scenarios.'),'#enterprise/manpower',t('افتح تخطيط القوى العاملة','Open Manpower Planning'),[t('3 سيناريوهات','3 scenarios'),t('فجوة FTE','FTE gap'),t('Gap → OD','Gap → OD')])+
phaseCard('03',t('التعويضات','Compensation'),t('اربط الدرجة بنطاق الراتب المعتمد لدى الجهة، واحسب positioning وcompa-ratio والأثر السنوي دون اختلاق بيانات سوقية غير موثقة.','Connect the grade to the organization-approved salary band and calculate positioning, compa-ratio and annual cost impact without inventing unsupported market pay data.'),'#enterprise/compensation',t('افتح التعويضات','Open Compensation'),[t('Salary Bands','Salary Bands'),t('Compa-ratio','Compa-ratio'),t('أثر التكلفة','Cost impact')])+
'</div><div class="release-foundation"><div><strong>'+t('تهيئة مؤسسية لمرة واحدة','ONE-TIME INSTITUTION SETUP')+'</strong><p>'+t('حمّل الهيكل التنظيمي وهيكل الدرجات المعتمد مرة واحدة، ليستخدمهما محرك OD في كل طلب جديد.','Configure the approved organization structure and grade architecture once, then reuse them across OD decisions.')+'</p></div><div><strong>'+t('مرجع سعودي مدمج','SAUDI REFERENCE LAYER')+'</strong><p>'+t('5,041 مهنة، 599 تخصصًا تعليميًا، تنبيهات التوطين والترخيص، مع إبقاء كل متطلب غير متحقق ظاهرًا للمراجعة.','5,041 occupations, 599 education specializations, Saudization/licensing review signals, with unverified requirements kept visibly pending.')+'</p></div><div><strong>'+t('حوكمة القرار','DECISION GOVERNANCE')+'</strong><p>'+t('إصدارات، صلاحيات، مراجعات مستقلة، أدلة تقييم، ومخرجات PDF/DOCX/XLSX مرتبطة بالنسخة التي تمت مراجعتها.','Revisions, permissions, independent reviews, evaluation evidence, and PDF/DOCX/XLSX outputs tied to the reviewed revision.')+'</p></div></div><div class="release-cta"><div><span>'+t('المسار الكامل','END-TO-END FLOW')+'</span><strong>'+t('Strategy → OD → Evaluation → Manpower → Compensation → Approval','Strategy → OD → Evaluation → Manpower → Compensation → Approval')+'</strong></div><a class="lp-button lp-primary" href="#enterprise/create">'+t('ابدأ بقرار عمل حقيقي','Start with a real business need')+'</a></div></div></section>';}
function apply(){
 const home=document.getElementById('view-home');if(!home||home.hidden||!home.querySelector('.lp-hero'))return false;
 const copy=home.querySelector('.lp-hero-copy');
 if(copy){const eyebrow=copy.querySelector('.lp-eyebrow');if(eyebrow)eyebrow.textContent=t('ذكاء القوى العاملة من الاستراتيجية إلى التعويض','STRATEGY-TO-WORKFORCE INTELLIGENCE');const title=copy.querySelector('h1');if(title)title.innerHTML=t('ابدأ بالهدف الاستراتيجي.<br><em>صمّم الوظيفة، خطّط العدد،<br class="lp-wide-break"> واربط التعويض.</em>','Start with the strategic objective.<br><em>Design the job, plan capacity,<br class="lp-wide-break"> and connect compensation.</em>');const p=copy.querySelector('h1 + p');if(p)p.textContent=t('معيار منصة قرار للقوى العاملة تربط التطوير التنظيمي وتقييم الوظائف وتخطيط القوى العاملة والتعويضات بالتصنيف السعودي والتعليم والحوكمة المؤسسية.','Miyar is a workforce decision platform connecting organization development, job evaluation, manpower planning and compensation with Saudi occupation/education references and institutional governance.');const caption=copy.querySelector('.lp-caption');if(caption)caption.textContent=t('المحركات العامة تستخدم حسابات وقواعد شفافة. التنبؤات والرواتب والامتثال لا تُدّعى دون بيانات أو مصادر معتمدة.','Public engines use transparent rules and calculations. Forecasts, pay data and compliance are not claimed without approved inputs or sources.');}
 const nav=home.querySelector('.lp-nav');if(nav&&!nav.querySelector('[data-release-nav]')){const links=[['#enterprise/create',t('OD','OD')],['#enterprise/manpower',t('تخطيط القوى العاملة','Manpower')],['#enterprise/compensation',t('التعويضات','Compensation')]];for(const [href,label] of links){const a=document.createElement('a');a.href=href;a.dataset.releaseNav='1';a.textContent=label;nav.insertBefore(a,nav.querySelector('[href="#enterprise/overview"]'));}}
 if(!home.querySelector('#miyar-release-home')){const proof=home.querySelector('.lp-proof');if(proof)proof.insertAdjacentHTML('afterend',suite());else home.querySelector('main')?.insertAdjacentHTML('beforeend',suite());}
 return true;
}
let scheduled=false;function schedule(){if(scheduled)return;scheduled=true;setTimeout(()=>{scheduled=false;apply();},0);}const observer=new MutationObserver(schedule);observer.observe(document.documentElement,{subtree:true,childList:true});window.addEventListener('hashchange',schedule);window.addEventListener('miyar:navigate',schedule);document.addEventListener('DOMContentLoaded',schedule);schedule();window.MiyarReleaseHome={apply};
})();